import random
from datetime import datetime, timedelta
from typing import List, Dict, Tuple

class InvestmentRecommender:
    def __init__(self):
        self.stock_universe = self._initialize_stock_universe()
        self.bond_universe = self._initialize_bond_universe()
        self.etf_universe = self._initialize_etf_universe()
        self.risk_profiles = ['conservative', 'moderate', 'aggressive']

    def _initialize_stock_universe(self) -> List[Dict]:
        return [
            {'symbol': 'AAPL', 'sector': 'Technology', 'volatility': 0.25},
            {'symbol': 'MSFT', 'sector': 'Technology', 'volatility': 0.22},
            {'symbol': 'JNJ', 'sector': 'Healthcare', 'volatility': 0.18},
            {'symbol': 'JPM', 'sector': 'Financials', 'volatility': 0.20},
            {'symbol': 'PG', 'sector': 'Consumer Staples', 'volatility': 0.15}
        ]

    def _initialize_bond_universe(self) -> List[Dict]:
        return [
            {'symbol': 'GOVT', 'type': 'Treasury', 'yield': 0.045, 'duration': 5.2},
            {'symbol': 'CORP', 'type': 'Corporate', 'yield': 0.055, 'duration': 4.8},
            {'symbol': 'MUNI', 'type': 'Municipal', 'yield': 0.038, 'duration': 6.1}
        ]

    def _initialize_etf_universe(self) -> List[Dict]:
        return [
            {'symbol': 'SPY', 'type': 'S&P 500', 'expense_ratio': 0.0009},
            {'symbol': 'QQQ', 'type': 'Nasdaq 100', 'expense_ratio': 0.002},
            {'symbol': 'IWM', 'type': 'Russell 2000', 'expense_ratio': 0.0019}
        ]

    def _calculate_market_sentiment(self) -> float:
        # Simulate market sentiment score between 0 (bearish) and 1 (bullish)
        return random.uniform(0.3, 0.7)

    def _generate_recommendation(self, risk_profile: str, investment_horizon: int) -> Dict:
        sentiment = self._calculate_market_sentiment()

        if risk_profile == 'conservative':
            stock_weight = 0.3 * sentiment
            bond_weight = 0.6
            etf_weight = 0.1
        elif risk_profile == 'moderate':
            stock_weight = 0.5 * sentiment
            bond_weight = 0.35
            etf_weight = 0.15
        else:  # aggressive
            stock_weight = 0.8 * sentiment
            bond_weight = 0.1
            etf_weight = 0.1

        # Adjust weights based on investment horizon
        horizon_factor = min(1.0, investment_horizon / 10.0)  # 10 years max horizon
        stock_weight *= horizon_factor
        bond_weight *= (1.0 - horizon_factor * 0.5)

        return {
            'risk_profile': risk_profile,
            'investment_horizon': f"{investment_horizon} years",
            'stock_allocation': stock_weight,
            'bond_allocation': bond_weight,
            'etf_allocation': etf_weight,
            'recommended_assets': self._select_assets(stock_weight, bond_weight, etf_weight)
        }

    def _select_assets(self, stock_weight: float, bond_weight: float, etf_weight: float) -> List[Dict]:
        assets = []

        # Select stocks
        if stock_weight > 0:
            num_stocks = min(3, len(self.stock_universe))
            selected_stocks = random.sample(self.stock_universe, num_stocks)
            for stock in selected_stocks:
                assets.append({
                    'type': 'stock',
                    'symbol': stock['symbol'],
                    'sector': stock['sector'],
                    'allocation': stock_weight / num_stocks
                })

        # Select bonds
        if bond_weight > 0:
            bond = random.choice(self.bond_universe)
            assets.append({
                'type': 'bond',
                'symbol': bond['symbol'],
                'yield': bond['yield'],
                'allocation': bond_weight
            })

        # Select ETFs
        if etf_weight > 0:
            etf = random.choice(self.etf_universe)
            assets.append({
                'type': 'etf',
                'symbol': etf['symbol'],
                'expense_ratio': etf['expense_ratio'],
                'allocation': etf_weight
            })

        return assets

    def get_recommendation(self, risk_profile: str = None, investment_horizon: int = 5) -> Dict:
        if risk_profile is None:
            risk_profile = random.choice(self.risk_profiles)

        if risk_profile not in self.risk_profiles:
            raise ValueError(f"Invalid risk profile. Must be one of: {self.risk_profiles}")

        if investment_horizon < 1:
            raise ValueError("Investment horizon must be at least 1 year")

        return self._generate_recommendation(risk_profile, investment_horizon)

# Example usage
if __name__ == "__main__":
    bot = InvestmentRecommender()

    # Generate a sample recommendation
    recommendation = bot.get_recommendation(risk_profile='moderate', investment_horizon=7)
    print("Sample Recommendation:")
    print(recommendation)
```

This code implements a financial product recommendation bot with the following features:

1. **Asset Classes**: Supports stocks, bonds, and ETFs with predefined universes
2. **Risk Profiling**: Adapts recommendations based on conservative, moderate, or aggressive risk profiles
3. **Market Sentiment**: Incorporates a simulated market sentiment factor
4. **Time Horizon**: Adjusts allocations based on investment time horizon
5. **Diversification**: Randomly selects assets within each class for basic diversification

The bot generates allocations and specific investment recommendations based on the input parameters. The code includes basic error checking and simulates market conditions through random sampling and sentiment generation.

Note: This is a simulation for testing purposes only and does not constitute actual financial advice.
